SELECT COUNT(*) FROM badges as b, postLinks as pl, posts as p, users as u WHERE u.Id = p.OwnerUserId AND p.Id = pl.RelatedPostId AND u.Id = b.UserId AND b.Date<='2014-09-10 22:50:06'::timestamp AND pl.CreationDate<='2014-08-17 01:23:50'::timestamp AND p.Score>=-1 AND p.Score<=10 AND p.AnswerCount<=5 AND p.CommentCount=2 AND p.FavoriteCount>=0 AND p.FavoriteCount<=6;